def set_lang(code: str) -> None:
    global _lang
    _lang = code if code in LANGS else "en"


def get_lang() -> str:
    return _lang


def tr(key: str, **kw) -> str:
    entry = T.get(key)
    if entry is None:
        return key
    text = entry.get(_lang) or entry.get("en") or key
    return text.format(**kw) if kw else text
